sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float start;
uniform float end;
uniform float angle;
uniform float feather;
uniform float softness;
uniform float style;
half4 main(float2 coord) {
    float a = radians(angle);
    float2 d = float2(cos(a), sin(a));
    float2 g = style > 0.5 ? d / size : d / (abs(size.x * d.x) + abs(size.y * d.y));
    float x = dot(coord - size * 0.5, g) + 0.5;
    float w = max(feather, 1.0) * length(g);
    float m = clamp((x - start) / w + 0.5, 0.0, 1.0) * clamp((end - x) / w + 0.5, 0.0, 1.0);
    if (softness > 0.0) {
        float soft = softness * 0.01;
        m = smoothstep(start - soft, start, x) * (1.0 - smoothstep(end, end + soft, x));
    }
    return image.eval(coord) * half(m);
}
